-- A school database: students and courses, linked by enrollments.
CREATE TABLE students (id INTEGER PRIMARY KEY, name TEXT, city TEXT);
CREATE TABLE courses (id INTEGER PRIMARY KEY, title TEXT, teacher TEXT);
CREATE TABLE enrollments (
  student_id INTEGER REFERENCES students(id),
  course_id INTEGER REFERENCES courses(id),
  grade INTEGER
);
INSERT INTO students VALUES (1, 'Ana', 'Austin'), (2, 'Ben', 'Denver'), (3, 'Chen', 'Austin'), (4, 'Dara', 'Boston');
