-- A tiny online shop, designed from scratch.
CREATE TABLE customers (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE
);
CREATE TABLE products (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  price REAL NOT NULL CHECK (price >= 0),
  stock INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE orders (
  id INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL REFERENCES customers(id),
  product_id INTEGER NOT NULL REFERENCES products(id),
  quantity INTEGER NOT NULL CHECK (quantity > 0),
  ordered_on TEXT NOT NULL
);
INSERT INTO customers (name, email) VALUES ('Ana', 'ana@example.com'), ('Ben', 'ben@example.com');
INSERT INTO products (name, price, stock) VALUES ('Notebook', 2.50, 100), ('Headphones', 25.00, 10);

BEGIN;
INSERT INTO orders (customer_id, product_id, quantity, ordered_on) VALUES (1, 2, 2, '2026-03-14');
UPDATE products SET stock = stock - 2 WHERE id = 2;
COMMIT;

SELECT c.name, p.name AS product, o.quantity, o.quantity * p.price AS total
FROM orders o
JOIN customers c ON c.id = o.customer_id
JOIN products p ON p.id = o.product_id;

SELECT name, stock FROM products;

